n\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [688, 528, 942, 573], \"page_id\": 128}], \"content\": \"Highway Account\", \"description\": null, \"id\": 5, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [685, 599, 945, 625], \"page_id\": 128}], \"content\": \"[In billions of dollars. Source: DOT]\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [144, 625, 1486, 860], \"page_id\": 128}], \"content\": \"<table><tr><td>Commitments (unobligated balances plus unpaid obligations, FY 2003)</td><td>76.33</td></tr><tr><td>less:</td><td></td></tr><tr><td>Cash balance (FY 2003)</td><td>18.36</td></tr><tr><td>Unfunded authorizations (FY 2003).</td><td>57.97</td></tr><tr><td>24-month revenue estimate (fiscal 2004 and 2005)</td><td>60.35</td></tr></table>\", \"description\": null, \"id\": 7, \"type\": \"table\"}, {\"bbox\": [{\"coord\": [663, 952, 965, 985], \"page_id\": 128}], \"content\": \"Mass Transit Account\", \"description\": null, \"id\": 8, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [685, 1014, 944, 1044], \"page_id\": 128}], \"content\": \"[In billions of dollars. Source: DOT]\", \"description\": null, \"id\": 9, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [140, 1056, 1490, 1280], \"page_id\": 128}], \"content\": \"<table><tr><td>Commitments (unobligated balances plus unpaid obligations, FY 2003)</td><td>0.24</td></tr><tr><td>less:</td><td></td></tr><tr><td>Cash balance (FY 2003)</td><td>4.34</td></tr><tr><td>Unfunded authorizations (FY 2003)</td><td>-4.10</td></tr><tr><td>24-month revenue estimate (fiscal 2004 and 2005)</td><td>9.77</td></tr></table>\", \"description\": null, \"id\": 10, \"type\": \"table\"}, {\"bbox\": [{\"coord\": [1443, 94, 1488, 125], \"page_id\": 129}], \"content\": \"131\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [397, 196, 1229, 236], \"page_id\": 129}], \"content\": \"INTRODUCTION: Inland Waterways Trust Fund\", \"description\": null, \"id\": 1, \"type\": \"title\"}, {\"bbox\": [{\"coord\": [144, 248, 792, 500], \"page_id\": 129}], \"content\": \"The Inland Waterways Trust Fund was established by the Treasury in fiscal 1984, pursuant to section 203 of the Inland Waterways Revenue Act of 1978 (Public Law 95-502) and continued pursuant to section 1405 of the Water Resources Development Act of 1986 (Public Law 99-662, codified at 26 United States Code 9506). Under 26 United States Code 9506(b), amounts from taxes on fuel used in commercial trans- portation on inland waterways, as determined by the Secretary of the Treasury, are appropriated to the trust fund.\", \"description\": null, \"id\": 2, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [144, 500, 794, 667], \"page_id\": 129}], \"content\": \"The Technical and Miscellaneous Revenue Act of 1988 (Public Law 100-647, approved November 10, 1988) increased the tax each year, 1990 through 1995. These amounts are transferred quarterly from the general fund based on estimates made by the Secretary, subject to adjustments in later transfers to the amounts of actual tax receipts.\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [142, 669, 798, 726], \"page_id\": 129}], \"content\": \"The Secretary of the Treasury invests in interest-bearing obligations of the United States that portion of the trust fund,\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [840, 245, 1490, 526], \"page_id\": 129}], \"content\": \"in his judgment, not required to meet current withdrawals. The interest on, and proceeds from, the sale or redemption of any obligation held in the trust fund is credited to the trust fund. The Inland Waterways Revenue Act of 1978 (Public Law 95-502) provides that amounts in the trust fund shall be available as provided, by appropriations acts, for construction and rehabilitation expenditures for navigation on the inland and intracoastal waterways of the United States described in 33 United States Code 1804. Expenditures must be otherwise authorized by law.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [838, 533, 1490, 707], \"page_id\": 129}], \"content\": \"Annual reports to Congress are required by 26 United States Code 9602(a) to be submitted by the Secretary of the Treasury. These reports are required to cover the financial condition and the results of operations of the fund during the past fiscal year and its expected condition and operations during the next 5 fiscal years.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [488, 792, 1148, 860], \"page_id\": 129}], \"content\": \"TABLE TF-16.\\u2014Inland Waterways Trust Fund Results of Operations, Fiscal 2001\", \"description\": null, \"id\": 7, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [621, 891, 1013, 912], \"page_id\": 129}], \"content\": \"[Source: Department of the Army Corps of Engineers]\", \"description\": null, \"id\": 8, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [148, 931, 1479, 1223], \"page_id\": 129}], \"content\": \"<table><tr><td>Balance Oct. 1, 2000</td><td>$387,789,480</td></tr><tr><td>Receipts:</td><td></td></tr><tr><td>Fuel taxes/revenues</td><td>112,683,000</td></tr><tr><td>Interest on investments</td><td>20,900,958</td></tr><tr><td>Total receipts</td><td>133,583,958</td></tr><tr><td>Transfers:</td><td></td></tr><tr><td>Corps of Engineers</td><td>110,220,630</td></tr><tr><td>Balance Sept. 30, 2001</td><td>$411,152,808</td></tr></table>\", \"description\": null, \"id\": 9, \"type\": \"table\"}, {\"bbox\": [{\"coord\": [148, 1266, 780, 1318], \"page_id\": 129}], \"content\": \"* The source for fiscal 2001 beginning and ending balance is from the Bureau of the Public Debt, Office of Public Debt Accounting, Division of Federal Investments, Trust Fund Management Branch.\", \"description\": null, \"id\": 10, \"type\": \"footnote\"}, {\"bbox\": [{\"coord\": [497, 1355, 1137, 1424], \"page_id\": 129}], \"content\": \"Expected Condition and Results of Operations Fiscal 2002-2006 *\", \"description\": null, \"id\": 11, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [552, 1452, 1086, 1473], \"page_id\": 129}], \"content\": \"[In millions of dollars. Source: Department of the Army Corps of Engineers]\", \"description\": null, \"id\": 12, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [142, 1497, 1499, 1815], \"page_id\": 129}], \"content\": \"<table><tr><th></th><th>2002</th><th>2003</th><th>2004</th><th>2005</th><th>2006</th></tr><tr><td>Balance Oct. 1</td><td>411.2</td><td>457.4</td><td>490.6</td><td>479.0</td><td>461.9</td></tr><tr><td>Receipts:</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>Fuel taxes</td><td>105.5</td><td>106.9</td><td>108.3</td><td>109.7</td><td>111.1</td></tr><tr><td>Interest on investments</td><td>23.0</td><td>26.3</td><td>28.2</td><td>27.5</td><td>26.6</td></tr><tr><td>Total receipts</td><td>128.5</td><td>133.2</td><td>136.5</td><td>137.2</td><td>137.7</td></tr><tr><td>Transfers:</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>Corps of Engineers</td><td>82.3</td><td>100.0</td><td>148.1</td><td>154.4</td><td>169.4</td></tr><tr><td>Balance Sept. 30</td><td>457.4</td><td>490.6</td><td>479.0</td><td>461.9</td><td>430.1</td></tr></table>\", \"description\": null, \"id\": 13, \"type\": \"table\"}, {\"bbox\": [{\"coord\": [142, 1864, 794, 1898], \"page_id\": 129}], \"content\": \"* Outyear projections are based on economic conditions and agencies' best projections of revenues and expenditures.\", \"description\": null, \"id\": 14, \"type\": \"footnote\"}, {\"bbox\": [{\"coord\": [138, 97, 199, 132], \"page_id\": 130}], \"content\": \"132\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [235, 191, 1392, 238], \"page_id\": 130}], \"content\": \"INTRODUCTION: Leaking Underground Storage Tank Trust Fund\", \"description\": null, \"id\": 1, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [133, 243, 800, 556], \"page_id\": 130}], \"content\": \"The Leaking Underground Storage Tank (LUST) Trust Fund was established in fiscal 1981 according to provisions of the Comprehensive Environmental Response, Compensation and Liability Act of 1980 (Public Law 96-510, codified at 26 United States Code 9508), as amended by the Superfund Amendments and Re-authorization Act of 1986 (Public Law 99-499, dated October 17, 1986), sections 13163(c) and 13242(d)(42) of the Omnibus Budget Reconciliation Act of 1993 (Public Law 103-66, dated August 10, 1993), and section 1032(e)(13) of the Taxpayer Relief Act of 1987 (Public Law 105-34, dated August 5, 1997).\", \"description\": null, \"id\": 2, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [135, 559, 800, 627], \"page_id\": 130}], \"content\": \"The LUST Trust Fund is financed by taxes collected on gasoline, diesel fuels, special motor fuels, aviation fuels and\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [836, 248, 1494, 415], \"page_id\": 130}], \"content\": \"fuels used in commercial transportation on inland waterways. Amounts available in the LUST Trust Fund, exceeding current expenditure requirements, are invested by the Secretary of the Treasury in interest-bearing Government securities (e.g., Treasury bills). All interest earned is credited directly to the LUST Trust Fund.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [832, 417, 1492, 500], \"page_id\": 130}], \"content\": \"To carry out the LUST program, amounts are appropriated for the LUST Trust Fund to the EPA for programmatic and administrative expenses.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [836, 497, 1492, 641], \"page_id\": 130}], \"content\": \"An annual report to Congress by the Secretary of the Treasury is required by 26 United States Code 9602(a). These reports present the financial condition of the LUST Trust Fund and results of operations for the past fiscal year and its expected condition and operations during the next 5 fiscal years.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [361, 674, 1270, 740], \"page_id\": 130}], \"content\": \"TABLE TF-17.\\u2014Leaking Underground Storage Tank Trust Fund Results of Operations, Fiscal 2001\", \"description\": null, \"id\": 7, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [760, 759, 871, 797], \"page_id\": 130}], \"content\": \"[Source: EPA]\", \"description\": null, \"id\": 8, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [140, 799, 1490, 1308], \"page_id\": 130}], \"content\": \"<table><tr><td>Balance Oct. 1, 2000.</td><td>$1,568,000,000</td></tr><tr><td>Receipts:</td><td></td></tr><tr><td>Taxes</td><td>179,000,000</td></tr><tr><td>Interest</td><td>18,000,000</td></tr><tr><td>Gross tax receipts</td><td>197,000,000</td></tr><tr><td>Undisbursed balances:</td><td></td></tr><tr><td>Environmental Protection Agency Leaking Underground Storage Tank balances</td><td>70,000,000</td></tr><tr><td>Total undisbursed balances</td><td>70,000,000</td></tr><tr><td>Expenses:</td><td></td></tr><tr><td>Environmental Protection Agency Leaking Underground Storage Tank expenses</td><td>72,000,000</td></tr><tr><td>Total expenses</td><td>72,000,000</td></tr><tr><td>Balance Sept. 30, 2001</td><td>$1,693,000,000</td></tr></table>\", \"description\": null, \"id\": 9, \"type\": \"table\"}, {\"bbox\": [{\"coord\": [137, 1506, 1479, 1900], \"page_id\": 130}], \"content\": \"<table><tr><th></th><th>2002</th><th>2003</th><th>2004</th><th>2005</th><th>2006</th></tr><tr><td>Balance Oct. 1</td><td>1,693.0</td><td>1,907.8</td><td>2,142.5</td><td>2,391.4</td><td>2,658.6</td></tr><tr><td>Receipts:</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>Taxes</td><td>190.0</td><td>196.0</td><td>200.0</td><td>207.0</td><td>207.0</td></tr><tr><td>Interest</td><td>96.8</td><td>112.7</td><td>124.9</td><td>138.2</td><td>138.2</td></tr><tr><td>Total receipts</td><td>286.8</td><td>308.7</td><td>324.9</td><td>345.2</td><td>345.2</td></tr><tr><td>Expenses</td><td>72.0</td><td>74.0</td><td>76.0</td><td>78.0</td><td>78.0</td></tr><tr><td>Balance Sept. 30</td><td>1,907.8</td><td>2,142.5</td><td>2,391.4</td><td>2,658.6</td><td>2,925.8</td></tr></table>\", \"description\": null, \"id\": 10, \"type\": \"table\"}, {\"bbox\": [{\"coord\": [1444, 97, 1488, 125], \"page_id\": 131}], \"content\": \"133\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [483, 196, 1151, 231], \"page_id\": 131}], \"content\": \"INTRODUCTION: Nuclear Waste Fund\", \"description\": null, \"id\": 1, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [140, 248, 798, 469], \"page_id\": 131}], \"content\": \"The Nuclear Waste Fund was established on the books of the Treasury in fiscal 1983, according to section 302 of the Nuclear Waste Policy Act of 1982 [Public Law 97-425, codified at 42 United States Code 10222(c)]. Receipts represent fees collected from public utilities based on electricity generated by nuclear power reactors and spent nuclear fuel. Expenditures from the fund are for purposes of radioactive waste disposal activities.\", \"description\": null, \"id\": 2, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [142, 471, 798, 587], \"page_id\": 131}], \"content\": \"Amounts available in the fund exceeding current needs may be invested by the Secretary of the Treasury in obligations of the United States (1) having maturities in tandem with the needs of the waste fund and (2) bearing interest at rates deter-\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [840, 248, 1488, 420], \"page_id\": 131}], \"content\": \"mined appropriate, taking into consideration the current average market yield on outstanding marketable obligations of the United States with remaining periods to maturity comparable to the maturities of such investments, except that the interest rate on such investments shall not exceed the average interest rate applicable to existing borrowings.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [840, 420, 1488, 587], \"page_id\": 131}], \"content\": \"An annual report to Congress by the Secretary of the Treasury, after consultation with the Secretary of the Department of Energy (DOE), is required by 42 United States Code 10222(e)(1). This report must present the financial condition and the results of operations of the waste fund during the preceding fiscal year.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [559, 641, 1084, 710], \"page_id\": 131}], \"content\": \"TABLE TF-18.\\u2014Nuclear Waste Fund Results of Operations, Fiscal 2001\", \"description\": null, \"id\": 6, \"type\": \"caption\"}, {\"bbox\": [{\"coord\": [767, 733, 874, 757], \"page_id\": 131}], \"content\": \"[Source: DOE]\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [138, 787, 1484, 1744], \"page_id\": 131}], \"content\": \"<table><tr><td>Balance Oct. 1, 2000</td><td>$5,362,510</td></tr><tr><td>Receipts:</td><td></td></tr><tr><td>Fees collected</td><td>689,376,975</td></tr><tr><td>Penalties and interest on fee payments</td><td>14,648</td></tr><tr><td>Interest on investments</td><td>1,242,673,051</td></tr><tr><td>Total receipts</td><td>1,932,064,674</td></tr><tr><td>Nonexpenditure transfers:</td><td></td></tr><tr><td>SF-1151 transfers in (+)</td><td>11,938,362</td></tr><tr><td>SF-1151 transfers out (-)</td><td>11,938,362</td></tr><tr><td>Net Nonexpenditure transfers</td><td>-</td></tr><tr><td>Outlays:</td><td></td></tr><tr><td>DOE radioactive waste disposal activities</td><td>198,164,231</td></tr><tr><td>Cost of investments</td><td>1,738,237,017</td></tr><tr><td>Total outlays</td><td>1,936,401,248</td></tr><tr><td>Balance Sept. 30, 2001</td><td>$1,025,936</td></tr></table>\", \"description\": null, \"id\": 8, \"type\": \"table\"}, {\"bbox\": [{\"coord\": [137, 85, 197, 127], \"page_id\": 132}], \"content\": \"134\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [430, 189, 1204, 233], \"page_id\": 132}], \"content\": \"INTRODUCTION: Reforestation Trust Fund\", \"description\": null, \"id\": 1, \"type\": \"title\"}, {\"bbox\": [{\"coord\": [138, 243, 805, 415], \"page_id\": 132}], \"content\": \"The Reforestation Trust Fund was established on the books of the Treasury in fiscal 1981 to continue through September 30, 1985, according to provisions of Title III\\u2014Reforestation, of the Recreational Boating Safety and Facilities Improvement Act of 1980 [Public Law 96-451, codified at 16 United States Code 1606a(a)].\", \"description\": null, \"id\": 2, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [138, 420, 796, 667], \"page_id\": 132}], \"content\": \"The act provides that the Secretary of the Treasury shall transfer to the trust fund tariffs, limited to not more than $30 million for any fiscal year, received in the Treasury from October 1, 1979, through September 30, 1985, on (1) rough and primary wood products and wood waste; (2) lumber, flooring and moldings; and (3) wood veneers, plywood, other wood-veneer assemblies and building boards. Public Law 99-190, title II, 99 Statutes at Large 1245, extended the receipts for the trust fund. Amounts available in the reforestation\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [827, 243, 1503, 387], \"page_id\": 132}], \"content\": \"trust fund exceeding current withdrawals are invested in interest-bearing obligations of the United States or in obligations guaranteed as to both principal and interest by the United States. The interest on, and the proceeds from the sale or redemption of, any obligations are credited to the trust fund.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [840, 391, 1503, 523], \"page_id\": 132}], \"content\": \"The Secretary of the Department of Agriculture is authorized to obligate available sums in the trust fund (including any amounts not obligated in previous years) for (1) reforestation and timber stand improvement and (2) administrative costs of the Government for these activities.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [829, 526, 1494, 695], \"page_id\": 132}], \"content\": \"Annual reports are required by 16 United States Code 1606a(c)(1) to be submitted by the Secretary of the Treasury, after consultation with the Secretary of Agriculture, on the financial condition and the results of the operations of the trust fund during the past fiscal year and on its expected condition and operations during the next fiscal year.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [503, 768, 1124, 844], \"page_id\": 132}], \"content\": \"TABLE TF-19.\\u2014Reforestation Trust Fund Results of Operations, Fiscal 2001\", \"description\": null, \"id\": 7, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [667, 858, 958, 891], \"page_id\": 132}], \"content\": \"[Source: Department of Agriculture]\", \"description\": null, \"id\": 8, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [129, 898, 1508, 1292], \"page_id\": 132}], \"content\": \"<table><tr><td>Balance Oct. 1, 2000</td><td>$25,310,510</td></tr><tr><td>Receipts:</td><td></td></tr><tr><td>Excise taxes (tariffs)</td><td>30,000,000</td></tr><tr><td>Redemption of investment</td><td>-</td></tr><tr><td>Total receipts</td><td>30,000,000</td></tr><tr><td>Expenses:</td><td></td></tr><tr><td>Expenditure</td><td>26,013,639</td></tr><tr><td>Total expenses</td><td>26,013,639</td></tr><tr><td>Adjustment</td><td>-</td></tr><tr><td>Balance Sept. 30, 2001</td><td>$29,296,871</td></tr></table>\", \"description\": null, \"id\": 9, \"type\": \"table\"}, {\"bbox\": [{\"coord\": [415, 1450, 1228, 1527], \"page_id\": 132}], \"content\": \"TABLE TF-19.\\u2014Reforestation Trust Fund Expected Condition and Results of Operations, Fiscal 2002\", \"description\": null, \"id\": 10, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [592, 1544, 1042, 1575], \"page_id\": 132}], \"content\": \"[In thousands of dollars. Source: Department of Agriculture]\", \"description\": null, \"id\": 11, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [129, 1584, 1504, 1898], \"page_id\": 132}], \"content\": \"<table><tr><td>Balance Oct. 1</td><td>29,297</td></tr><tr><td>Receipts:</td><td></td></tr><tr><td>Excise taxes (tariffs)</td><td>30,000</td></tr><tr><td>Redemption of investment</td><td>240</td></tr><tr><td>Total receipts</td><td>30,240</td></tr><tr><td>Outlays</td><td>30,000</td></tr><tr><td>Balance Sept. 30</td><td>29,537</td></tr></table>\", \"description\": null, \"id\": 12, \"type\": \"table\"}, {\"bbox\": [{\"coord\": [723, 99, 909, 125], \"page_id\": 133}], \"content\": \"TRUST FUNDS\", \"description\": null, \"id\": 0, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [1444, 97, 1488, 125], \"page_id\": 133}], \"content\": \"135\", \"description\": null, \"id\": 1, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [386, 200, 1248, 243], \"page_id\": 133}], \"content\": \"CHARTS TF-D and E.\\u2014Major Trust Funds\", \"description\": null, \"id\": 2, \"type\": \"title\"}, {\"bbox\": [{\"coord\": [386, 252, 1244, 295], \"page_id\": 133}], \"content\": \"[Data depicted in these charts are derived from the Trust Fund tables, which are provided by various Government agencies. See tables TF-10, TF-12, TF-14, TF-15 and TF-18.]\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [137, 384, 199, 412], \"page_id\": 133}], \"content\": \"1800\", \"description\": null, \"id\": 4, \"type\": \"caption\"}, {\"bbox\": [{\"coord\": [135, 391, 1093, 1106], \"page_id\": 133}], \"content\": null, \"description\": null, \"id\": 5, \"type\": \"figure\"}, {\"bbox\": [{\"coord\": [1158, 401, 1484, 535], \"page_id\": 133}], \"content\": \"Interest on Investments, Fiscal 2000-2001\", \"description\": null, \"id\": 6, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [1149, 556, 1495, 707], \"page_id\": 133}], \"content\": null, \"description\": null, \"id\": 7, \"type\": \"figure\"}, {\"bbox\": [{\"coord\": [1142, 905, 1475, 962], \"page_id\": 133}], \"content\": \"* Interest on these investments was zero.\", \"description\": null, \"id\": 8, \"type\": \"caption\"}, {\"bbox\": [{\"coord\": [242, 1181, 494, 1318], \"page_id\": 133}], \"content\": \"Receipts and Expenses, Fiscal 2001\", \"description\": null, \"id\": 9, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [153, 1339, 514, 1563], \"page_id\": 133}], \"content\": null, \"description\": null, \"id\": 10, \"type\": \"figure\"}, {\"bbox\": [{\"coord\": [554, 1186, 1475, 1916], \"page_id\": 133}], \"content\": null, \"description\": null, \"id\": 11, \"type\": \"figure\"}, {\"bbox\": [{\"coord\": [137, 90, 191, 130], \"page_id\": 134}], \"content\": \"136\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [382, 196, 1250, 250], \"page_id\": 134}], \"content\": \"INTRODUCTION: Aquatic Resources Trust Fund\", \"description\": null, \"id\": 1, \"type\": \"title\"}, {\"bbox\": [{\"coord\": [144, 252, 809, 396], \"page_id\": 134}], \"content\": \"The Aquatic Resources Trust Fund was established on the books of the Treasury pursuant to the Deficit Reduction Act of 1984 [Public Law 98-369, division A, title X, section 1016(a), approved July 18, 1984]. The fund consists of two accounts: the Sport Fish Restoration Account and Boat Safety Account.\", \"description\": null, \"id\": 2, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [135, 398, 807, 509], \"page_id\": 134}], \"content\": \"Motorboat fuel taxes are transferred, in amounts up to $70 million per fiscal year, from the Highway Trust Fund to the Boat Safety Account. Authority for such transfers expires on October 1, 2003.\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [133, 512, 812, 874], \"page_id\": 134}], \"content\": \"Amounts equivalent to the excise taxes received on sport fishing equipment and import duties on fishing tackle, yachts and pleasure craft are appropriated into the Sport Fish Restoration Account. Motorboat fuel taxes not transferred to the Boat Safety Account or to the Land and Water Conservation Fund are transferred from the Highway Trust Fund to the Sport Fish Restoration Account. Transfers of motorboat fuel taxes from the Highway Trust Fund to the Land and Water Conservation Fund are limited to $1 million per fiscal year. In addition, pursuant to the Omnibus Budget Reconciliation Act of 1990 [Public Law 101-508, title XI, section 11211(i)(2) and (3)], small engine gasoline taxes are transferred to the Sport Fish Restoration Account.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [825, 255, 1503, 596], \"page_id\": 134}], \"content\": \"Amounts in the Sport Fish Restoration Account are used, as provided by appropriations acts, for the purposes of carrying out \\u201cAn Act to provide that the United States shall aid the States in fish restoration and management projects, and for other purposes,\\u201d approved August 9, 1950 (as in effect on the date of enactment of the Transportation Equity Act for the 21st Century (TEA-21) Restoration Act), the purposes of section 7404(d) of the Transportation Equity for the 21st Century (as in effect on the date of enactment of the TEA-21 Restoration Act), and the Coastal Wetlands Planning, Protection and Restoration Act (as in effect on the date of enactment of the TEA-21 Restoration Act).\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [823, 596, 1495, 705], \"page_id\": 134}], \"content\": \"Amounts in the Boat Safety Account, as provided by appropriations acts, are available to carry out the purposes of section 13106 of title 46, United States Code (as in effect on the date of enactment of the TEA-21 Restoration Act).\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [825, 705, 1497, 818], \"page_id\": 134}], \"content\": \"When the provisions of 26 United States Code 9602(b) are met, amounts available in the two accounts exceeding outlay requirements are invested in public debt securities with the interest credited to the respective accounts.\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [825, 820, 1499, 959], \"page_id\": 134}], \"content\": \"Annual reports to Congress, required by 26 United States Code 9602(a), are submitted by the Secretary of the Treasury. These reports are required to cover the financial condition and results of operations of the fund during the past fiscal year and those expected during the next 5 fiscal years.\", \"description\": null, \"id\": 8, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [317, 995, 1313, 1063], \"page_id\": 134}], \"content\": \"TABLE TF-20.\\u2014Aquatic Resources Trust Fund, Sport Fish Restoration Results of Operations, Fiscal 2001\", \"description\": null, \"id\": 9, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [683, 1089, 944, 1120], \"page_id\": 134}], \"content\": \"[Source: Bureau of the Public Debt]\", \"description\": null, \"id\": 10, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [133, 1122, 1503, 1862], \"page_id\": 134}], \"content\": \"<table><tr><td>Balance Oct. 1, 2000</td><td>$1,223,150,362 *</td></tr><tr><td>Revenue:</td><td></td></tr><tr><td>Tax revenue:</td><td></td></tr><tr><td>Gas, motorboat</td><td>183,622,000</td></tr><tr><td>Fish, equipment</td><td>117,494,716</td></tr><tr><td>Electric trolling sonar</td><td>2,226,000</td></tr><tr><td>Customs/import duties</td><td>34,771,495</td></tr><tr><td>Gas, motorboat, small engines</td><td>60,279,000</td></tr><tr><td>Total, tax revenue</td><td>398,393,211</td></tr><tr><td>Investment revenue:</td><td></td></tr><tr><td>Interest