ox\": [{\"coord\": [823, 375, 1488, 462], \"page_id\": 139}], \"content\": \"Assist United States wool producers in improving the quality of wool and wool production methods for wool produced in the United States.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [823, 476, 1488, 537], \"page_id\": 139}], \"content\": \"Disseminate information on improvements to United States wool producers.\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [823, 547, 1488, 608], \"page_id\": 139}], \"content\": \"Assist United States wool producers in developing and promoting the wool market.\", \"description\": null, \"id\": 8, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [823, 613, 1488, 728], \"page_id\": 139}], \"content\": \"Annual reports to Congress are required on the financial condition and the results of the operations of the trust fund during the past fiscal year and on its expected condition and operations during the next fiscal year.\", \"description\": null, \"id\": 9, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [301, 813, 1331, 882], \"page_id\": 139}], \"content\": \"TABLE TF-23.\\u2014Wool Research, Development, and Promotion Trust Fund Results of Operations, Fiscal 2001\", \"description\": null, \"id\": 10, \"type\": \"caption\"}, {\"bbox\": [{\"coord\": [603, 908, 1029, 929], \"page_id\": 139}], \"content\": \"[In thousands of dollars. Source: Department of Agriculture]\", \"description\": null, \"id\": 11, \"type\": \"caption\"}, {\"bbox\": [{\"coord\": [142, 931, 1490, 1285], \"page_id\": 139}], \"content\": \"<table><tr><td>Balance Oct. 1, 2000.</td><td>2,250</td></tr><tr><td>Receipts:</td><td></td></tr><tr><td>Harmonized Tariff</td><td>2,250</td></tr><tr><td>Total Receipts.</td><td>2,250</td></tr><tr><td>Expenses:</td><td></td></tr><tr><td>Expenditure</td><td>4,500</td></tr><tr><td>Total Expenses</td><td>4,500</td></tr><tr><td>Balance Sept. 30, 2001.</td><td>-</td></tr></table>\", \"description\