bbox\": [{\"coord\": [829, 243, 1490, 436], \"page_id\": 129}], \"content\": \"The 24-month revenue estimates for the highway and mass transit accounts, respectively, include the latest estimates received from Treasury's Office of Tax Analysis for excise taxes, net of refunds. They represent net highway receipts for those periods beginning at the close of fiscal 2004.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [690, 509, 938, 552], \"page_id\": 129}], \"content\": \"Highway Account\", \"description\": null, \"id\": 5, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [690, 561, 949, 587], \"page_id\": 129}], \"content\": \"(In billions of dollars. Source: DOT)\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [149, 613, 1484, 1504], \"page_id\": 129}], \"content\": \"<table><tr><td>Commitments (unobligated balances plus unpaid obligations, fiscal 2004)</td><td>74.67</td></tr><tr><td>less:</td><td></td></tr><tr><td>Cash balance (fiscal 2004)</td><td>15.05</td></tr><tr><td>Unfunded authorizations (fiscal 2004)</td><td>59.62</td></tr><tr><td>24-month revenue estimate (fiscal 2005 and 2006)</td><td>63.30</td></tr></table><table><tr><td colspan=\\\"2\\\"><b>Mass Transit Account</b></td></tr><tr><td colspan=\\\"2\\\">[In billions of dollars. Source: DOT]</td></tr><tr><td>Commitments (unobligated balances plus unpaid obligations, fiscal 2004)</td><td>5.19</td></tr><tr><td>less:</td><td></td></tr><tr><td>Cash balance (fiscal 2004)</td><td>8.21</td></tr><tr><td>Unfunded authorizations (fiscal 2004)</td><td>-3.02</td></tr><tr><td>24-month revenue estimate (fiscal 2005 and 2006)</td><td>9.98</td></tr></table>\", \"description\": null, \"id\": 7, \"type\": \"table\"}, {\"bbox\": [{\"coord\": [718, 94, 916, 127], \"page_id\": 130}], \"content\": \"TRUST FUNDS\", \"description\": null, \"id\": 0, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [1441, 97, 1495, 127], \"page_id\": 130}], \"content\": \"129\", \"description\": null, \"id\": 1, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [390, 203, 1239, 252], \"page_id\": 130}], \"content\": \"INTRODUCTION: Inland Waterways Trust Fund\", \"description\": null, \"id\": 2, \"type\": \"title\"}, {\"bbox\": [{\"coord\": [129, 266, 807, 544], \"page_id\": 130}], \"content\": \"The Inland Waterways Trust Fund was established by the Treasury in fiscal 1984, pursuant to section 203 of the Inland Waterways Revenue Act of 1978 (Public Law 95-502) and continued pursuant to section 1405 of the Water Resources Development Act of 1986 (Public Law 99-662, codified at 26 United States Code 9506). Under 26 United States Code 9506(b), amounts from taxes on fuel used in commercial transportation on inland waterways, as determined by the Secretary of the Treasury, are appropriated to the trust fund.\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [129, 544, 807, 754], \"page_id\": 130}], \"content\": \"The Technical and Miscellaneous Revenue Act of 1988 (Public Law 100-647, approved November 10, 1988) increased the tax each year, 1990 through 1995. These amounts are transferred quarterly from the general fund based on estimates made by the Secretary, subject to adjustments in later transfers to the amounts of actual tax receipts.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [129, 757, 807, 820], \"page_id\": 130}], \"content\": \"The Secretary of the Treasury invests in interest-bearing obligations of the United States that portion of the trust fund,\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [827, 269, 1495, 573], \"page_id\": 130}], \"content\": \"in his judgment, not required to meet current withdrawals. The interest on, and proceeds from, the sale or redemption of any obligation held in the trust fund is credited to the trust fund. The Inland Waterways Revenue Act of 1978 (Public Law 95-502) provides that amounts in the trust fund shall be available as provided, by appropriations acts, for construction and rehabilitation expenditures for navigation on the inland and intracoastal waterways of the United States described in 33 United States Code 1804. Expenditures must be otherwise authorized by law.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [825, 573, 1495, 757], \"page_id\": 130}], \"content\": \"Annual reports to Congress are required by 26 United States Code 9602(a) to be submitted by the Secretary of the Treasury. These reports are required to cover the financial condition and the results of operations of the fund during the past fiscal year and its expected condition and operations during the next 5 fiscal years.\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [484, 867, 1166, 948], \"page_id\": 130}], \"content\": \"TABLE TF-16.\\u2014Inland Waterways Trust Fund Results of Operations, Fiscal 2002\", \"description\": null, \"id\": 8, \"type\": \"caption\"}, {\"bbox\": [{\"coord\": [545, 957, 949, 988], \"page_id\": 130}], \"content\": \"[Source: Department of the Army Corps of Engineers]\", \"description\": null, \"id\": 9, \"type\": \"caption\"}, {\"bbox\": [{\"coord\": [146, 983, 1484, 1256], \"page_id\": 130}], \"content\": \"<table><tr><td>Balance Oct. 1, 2001</td><td>$411,152,80</td></tr><tr><td>Receipts:</td><td></td></tr><tr><td>Fuel taxes/revenues</td><td>95,284,000</td></tr><tr><td>Interest on investments</td><td>12,397,115</td></tr><tr><td>Total receipts</td><td>107,681,115</td></tr><tr><td>Transfers:</td><td></td></tr><tr><td>Corps of Engineers</td><td>106,198,787</td></tr><tr><td>Balance Sept. 30, 2002</td><td>$412,635,13 *</td></tr></table>\", \"description\": null, \"id\": 10, \"type\": \"table\"}, {\"bbox\": [{\"coord\": [146, 1292, 807, 1358], \"page_id\": 130}], \"content\": \"* The source for fiscal 2002 beginning and ending balance is from the Bureau of the Public Debt, Office of 