e\": \"page_number\"}, {\"bbox\": [{\"coord\": [718, 94, 913, 125], \"page_id\": 131}], \"content\": \"TRUST FUNDS\", \"description\": null, \"id\": 1, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [235, 191, 1397, 240], \"page_id\": 131}], \"content\": \"INTRODUCTION: Leaking Underground Storage Tank Trust Fund\", \"description\": null, \"id\": 2, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [138, 250, 801, 618], \"page_id\": 131}], \"content\": \"The Leaking Underground Storage Tank (LUST) Trust Fund was established in fiscal 1981 according to provisions of the Comprehensive Environmental Response, Compensation and Liability Act of 1980 (Public Law 96-510, codified at 26 United States Code 9508), as amended by the Superfund Amendments and Re-authorization Act of 1986 (Public Law 99-499, dated October 17, 1986), sections 13163(c) and 13242(d)(42) of the Omnibus Budget Reconciliation Act of 1993 (Public Law 103-66, dated August 10, 1993), and section 1032(e)(13) of the Taxpayer Relief Act of 1987 (Public Law 105-34, dated August 5, 1997).\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [140, 618, 801, 712], \"page_id\": 131}], \"content\": \"The LUST Trust Fund is financed by taxes collected on gasoline, diesel fuels, special motor fuels, aviation fuels and fuels used in commercial transportation on inland\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [831, 250, 1494, 403], \"page_id\": 131}], \"content\": \"waterways. Amounts available in the LUST Trust Fund, exceeding current expenditure requirements, are invested by the Secretary of the Treasury in interest-bearing Government securities (e.g., Treasury bills). All interest eamed is credited directly to the LUST Trust Fund.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [831, 403, 1494, 500], \"page_id\": 131}], \"content\": \"To carry out the LUST program, amounts are appropriated for the LUST Trust Fund to the EPA for programmatic and administrative expenses.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [831, 500, 1490, 681], \"page_id\": 131}], \"content\": \"An annual report to Congress by the Secretary of the Treasury is required by 26 United States Code 9602(a). These reports present the financial condition of the LUST Trust Fund and results of operations for the past fiscal year and its expected condition and operations during the next 5 fiscal years.\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [357, 766, 1277, 834], \"page_id\": 131}], \"content\": \"TABLE TF-17.\\u2014Leaking Underground Storage Tank Trust Fund Results of Operations, Fiscal 2002\", \"description\": null, \"id\": 8, \"type\": \"caption\"}, {\"bbox\": [{\"coord\": [142, 844, 1490, 1372], \"page_id\": 131}], \"content\": \"<table><tr><th colspan=\\\"2\\\">(Source: EPA)</th></tr><tr><td>Balance Oct. 1, 2001</td><td>$1,624,000,000*</td></tr><tr><th colspan=\\\"2\\\">Receipts:</th></tr><tr><td>Taxes</td><td>181,100,000</td></tr><tr><td>Interest</td><td>90,000,000</td></tr><tr><td>Gross tax receipts</td><td>271,100,000</td></tr><tr><th colspan=\\\"2\\\">Undisbursed balances:</th></tr><tr><td>Environmental Protection Agency Leaking Underground Storage Tank balances</td><td>72,000,000</td></tr><tr><td>Total undisbursed balances</td><td>72,000,000</td></tr><tr><th colspan=\\\"2\\\">Expenses:</th></tr><tr><td>Environmental Protection Agency Leaking Underground Storage Tank expenses</td><td>73,000,000</td></tr><tr><td>Total expenses</td><td>73,000,000</td></tr><tr><td>Balance Sept. 30, 2002</td><td>$1,822,100,000</td></tr></table>\", \"description\": null, \"id\": 9, \"type\": \"table\"}, {\"bbox\": [{\"coord\": [149, 1395, 787, 1454], \"page_id\": 131}], \"content\": \"* Fiscal 2003 unavailable balance, start of year, has been adjusted downward $69 million to reflect a prior-year upward adjustment to obligated balances and to tie to the Treasury Combined Statement.\", \"description\": null, \"id\": 10, \"type\": \"footnote\"}, {\"bbox\": [{\"coord\": [373, 1513, 1259, 1589], \"page_id\": 131}], \"content\": \"Leaking Underground Storage Tank Trust Fund Expected Condition and Results of Operations, Fiscal 2003-2007\", \"description\": null, \"id\": 11, \"type\": \"caption\"}, {\"bbox\": [{\"coord\": [681, 1598, 945, 1624], \"page_id\": 131}], \"content\": \"[In millions of dollars. Source: EPA]\", \"description\": null, \"id\": 12, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [144, 1631, 1490, 1952], \"page_id\": 131}], \"content\": \"<table><tr><th></th><th>2003</th><th>2004</th><th>2005</th><th>2006</th><th>2007</th></tr><tr><td>Balance Oct. 1</td><td>1,822.0</td><td>2,018.0</td><td>2,202.0</td><td>2,420.0</td><td>2,654.0</td></tr><tr><td>Receipts:</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>Taxes</td><td>183.0</td><td>189.0</td><td>194.0</td><td>198.0</td><td>204.0</td></tr><tr><td>Interest</td><td>85.0</td><td>68.0</td><td>98.0</td><td>111.0</td><td>122.0</td></tr><tr><td>Total receipts</td><td>268.0</td><td>257.0</td><td>292.0</td><td>309.0</td><td>326.0</td></tr><tr><td>Appropriations</td><td>72.0</td><td>73.0</td><td>74.0</td><td>75.0</td><td>77.0</td></tr><tr><td>Balance Sept. 30</td><td>2,018.0</td><td>2,202.0</td><td>2,420.0</td><td>2,654.0</td><td>2,903.0</td></tr></table>\", \"description\": null, \"id\": 13, \"type\": \"table\"}, {\"bbox\": [{\"coord\": [718, 92, 909, 130], \"page_id\": 132}], \"content\": \"TRUST FUNDS\", \"description\": null, \"id\": 0, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [1437, 90, 1490, 127], \"page_id\": 132}], \"content\": \"131\", \"description\": null, \"id\": 1, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [477, 207, 1151, 250], \"page_id\": 132}], \"content\": \"INTRODUCTION: Nuclear Waste Fund\", \"description\": null, \"id\": 2, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [140, 266, 798, 512], \"page_id\": 132}], \"content\": \"The Nuclear Waste Fund was established on the books of the Treasury in fiscal 1983, according to section 302 of the Nuclear Waste Policy Act of 1982 [Public Law 97-425, codified at 42 United States Code 10222(c)]. Receipts represent fees collected from public utilities based on electricity generated by nuclear power reactors and spent nuclear fuel. Expenditures from the fund are for purposes of radioactive waste disposal activities.\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [140, 514, 798, 667], \"page_id\": 132}], \"content\": \"Amounts available in the fund exceeding current needs may be invested by the Secretary of the Treasury in obligations of the United States (1) having maturities in tandem with the needs of the waste fund and (2) bearing interest at rates determined appropriate, taking into\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [831, 266, 1494, 453], \"page_id\": 132}], \"content\": \"consideration the current average market yield on outstanding marketable obligations of the United States with remaining periods to maturity comparable to the maturities of such investments, except that the interest rate on such investments shall not exceed the average interest rate applicable to existing borrowings.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [832, 450, 1495, 639], \"page_id\": 132}], \"content\": \"An annual report to Congress by the Secretary of the Treasury, after consultation with the Secretary of the Department of Energy (DOE), is required by 42 United States Code 10222(e)(1). This report must present the financial condition and the results of operations of the waste fund during the preceding fiscal year.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [550, 721, 1076, 799], \"page_id\": 132}], \"content\": \"TABLE TF-18.\\u2014Nuclear Waste Fund Results of Operations, Fiscal 2002\", \"description\": null, \"id\": 7, \"type\": \"caption\"}, {\"bbox\": [{\"coord\": [151, 799, 1479, 1928], \"page_id\": 132}], \"content\": \"<table><tr><td colspan=\\\"2\\\">[Source: DOE]</td><td></td></tr><tr><td>Balance Oct. 1, 2001</td><td></td><td>$1,025,936</td></tr><tr><td>Receipts:</td><td></td><td></td></tr><tr><td>Fees collected</td><td></td><td>712,220,370</td></tr><tr><td>Penalties and interest on fee payments</td><td></td><td>5,204</td></tr><tr><td>Interest on investments</td><td></td><td>1,598,412,329</td></tr><tr><td>Total receipts</td><td></td><td>2,310,637,903</td></tr><tr><td>Nonexpenditure transfers:</td><td></td><td></td></tr><tr><td>SF-1151 transfers in (+)</td><td></td><td>-</td></tr><tr><td>SF-1151 transfers out (-)</td><td></td><td>-</td></tr><tr><td>Net Nonexpenditure transfers</td><td></td><td>-</td></tr><tr><td>Outlays:</td><td></td><td></td></tr><tr><td>DOE radioactive waste disposal activities</td><td></td><td>132,691,033</td></tr><tr><td>Cost of investments</td><td></td><td>2,178,129,098</td></tr><tr><td>Total outlays</td><td></td><td>2,310,820,131</td></tr><tr><td>Balance Sept. 30, 2002</td><td></td><td>$843,708</td></tr></table>\", \"description\": null, \"id\": 8, \"type\": \"table\"}, {\"bbox\": [{\"coord\": [138, 97, 197, 125], \"page_id\": 133}], \"content\": \"132\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [718, 94, 911, 130], \"page_id\": 133}], \"content\": \"TRUST FUNDS\", \"description\": null, \"id\": 1, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [353, 196, 1277, 248], \"page_id\": 133}], \"content\": \"CHARTS TF-D and E.\\u2014Major Trust Funds\", \"description\": null, \"id\": 2, \"type\": \"title\"}, {\"bbox\": [{\"coord\": [399, 243, 1275, 299], \"page_id\": 133}], \"content\": \"[Data depicted in these charts are derived from the Trust Fund tables, which are provided by various Government agencies. See tables TF-10, TF-12, TF-14, TF-15 and TF-18.]\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [151, 325, 1423, 985], \"page_id\": 133}], \"content\": null, \"description\": null, \"id\": 4, \"type\": \"figure\"}, {\"bbox\": [{\"coord\": [244, 1091, 541, 1280], \"page_id\": 133}], \"content\": \"Receipts and Expenses, Fiscal 2002\", \"description\": null, \"id\": 5, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [282, 1301, 506, 1341], \"page_id\": 133}], \"content\": \"(In billions of dollars)\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [586, 1065, 1450, 1766], \"page_id\": 133}], \"content\": null, \"description\": null, \"id\": 7, \"type\": \"figure\"}, {\"bbox\": [{\"coord\": [716, 94, 913, 127], \"page_id\": 134}], \"content\": \"TRUST FUNDS\", \"description\": null, \"id\": 0, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [1439, 97, 1488, 127], \"page_id\": 134}], \"content\": \"133\", \"description\": null, \"id\": 1, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [434, 205, 1197, 252], \"page_id\": 134}], \"content\": \"INTRODUCTION: Reforestation Trust Fund\", \"description\": null, \"id\": 2, \"type\": \"title\"}, {\"bbox\": [{\"coord\": [142, 266, 798, 453], \"page_id\": 134}], \"content\": \"The Reforestation Trust Fund was established on the books of the Treasury in fiscal 1981 to continue through September 30, 1985, according to provisions of Title III\\u2014Reforestation, of the Recreational Boating Safety and Facilities Improvement Act of 1980 [Public Law 96-451, codified at 16 United States Code 1606a(a)].\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [137, 453, 798, 790], \"page_id\": 134}], \"content\": \"The act provides that the Secretary of the Treasury shall transfer to the trust fund tariffs, limited to not more than $30 million for any fiscal year, received in the Treasury from October 1, 1979, through September 30, 1985, on (1) rough and primary wood products and wood waste; (2) lumber, flooring and moldings; and (3) wood veneers, plywood, other wood-veneer assemblies and building boards. Public Law 99-190, title II, 99 Statutes at Large 1245, extended the receipts for the trust fund. Amounts available in the reforestation trust fund exceeding current withdrawals are invested in interest-bearing obligations of the United States\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [831, 266, 1492, 389], \"page_id\": 134}], \"content\": \"or in obligations guaranteed as to both principal and interest by the United States. The interest on, and the proceeds from the sale or redemption of, any obligations are credited to the trust fund.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [829, 391, 1492, 542], \"page_id\": 134}], \"content\": \"The Secretary of the Department of Agriculture is authorized to obligate available sums in the trust fund (including any amounts not obligated in previous years) for (1) reforestation and timber stand improvement and (2) administrative costs of the Government for these activities.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [825, 544, 1495, 764], \"page_id\": 134}], \"content\": \"Annual reports are required by 16 United States Code 1606a(c) (1) to be submitted by the Secretary of the Treasury, after consultation with the Secretary of Agriculture, on the financial condition and the results of the operations of the trust fund during the past fiscal year and on its expected condition and operations during the next fiscal year.\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [515, 834, 1122, 877], \"page_id\": 134}], \"content\": \"TABLE TF-19.\\u2014Reforestation Trust Fund\", \"description\": null, \"id\": 8, \"type\": \"title\"}, {\"bbox\": [{\"coord\": [577, 879, 1051, 915], \"page_id\": 134}], \"content\": \"Results of Operations, Fiscal 2002\", \"description\": null, \"id\": 9, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [688, 919, 947, 952], \"page_id\": 134}], \"content\": \"[Source: Department of Agriculture]\", \"description\": null, \"id\": 10, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [148, 962, 1479, 1381], \"page_id\": 134}], \"content\": \"<table><tr><td>Balance Oct. 1, 2001</td><td>$29,296,871</td></tr><tr><td>Receipts:</td><td></td></tr><tr><td>Excise taxes (tariffs)</td><td>30,000,000</td></tr><tr><td>Redemption of investment</td><td>-</td></tr><tr><td>Total receipts</td><td>30,000,000</td></tr><tr><td>Expenses:</td><td></td></tr><tr><td>Expenditure</td><td>31,401,564</td></tr><tr><td>Total expenses</td><td>31,401,564</td></tr><tr><td>Adjustment</td><td>126,171 *</td></tr><tr><td>Balance Sept. 30, 2002</td><td>$28,021,478</td></tr></table>\", \"description\": null, \"id\": 11, \"type\": \"table\"}, {\"bbox\": [{\"coord\": [153, 1398, 792, 1459], \"page_id\": 134}], \"content\": \"* The adjustment in the amount of $126,171 for reforestation is caused by the net excess of funds received over the amount allowed by Public Law 96-451 mentioned in the Introduction of the Reforestation Trust Fund.\", \"description\": null, \"id\": 12, \"type\": \"footnote\"}, {\"bbox\": [{\"coord\": [412, 1499, 1222, 1584], \"page_id\": 134}], \"content\": \"Reforestation Trust Fund Expected Condition and Results of Operations, Fiscal 2003\", \"description\": null, \"id\": 13, \"type\": \"title\"}, {\"bbox\": [{\"coord\": [597, 1586, 1031, 1617], \"page_id\": 134}], \"content\": \"[In thousands of dollars. Source: Department of Agriculture]\", \"description\": null, \"id\": 14, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [146, 1619, 1483, 1921], \"page_id\": 134}], \"content\": \"<table><tr><td>Balance Oct. 1</td><td>28,021</td></tr><tr><td>Receipts:</td><td></td></tr><tr><td>Excise taxes (tariffs)</td><td>30,000</td></tr><tr><td>Redemption of investment</td><td>-</td></tr><tr><td>Total receipts</td><td>30,000</td></tr><tr><td>Outlays</td><td>31,000</td></tr><tr><td>Balance Sept. 30</td><td>27,021</td></tr></table>\", \"description\": null, \"id\": 15, \"type\": \"table\"}, {\"bbox\": [{\"coord\": [140, 99, 188, 123], \"page_id\": 135}], \"content\": \"134\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [719, 97, 909, 123], \"page_id\": 135}], \"content\": \"TRUST FUNDS\", \"description\": null, \"id\": 1, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [382, 193, 1240, 236], \"page_id\": 135}], \"content\": \"INTRODUCTION: Aquatic Resources Trust Fund\", \"description\": null, \"id\": 2, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [140, 250, 798, 434], \"page_id\": 135}], \"content\": \"The Aquatic Resources Trust Fund was established on the books of the Treasury pursuant to the Deficit Reduction Act of 1984 [Public Law 98-369, division A, title X, section 1016(a), approved July 18, 1984]. The fund consists of two accounts: the Sport Fish Restoration Account and Boat Safety Account.\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [140, 436, 798, 556], \"page_id\": 135}], \"content\": \"Motorboat fuel taxes are transferred, in amounts up to $70 million per fiscal year, from the Highway Trust Fund to the Boat Safety Account. Authority for such transfers expires on October 1, 2003.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [140, 559, 798, 957], \"page_id\": 135}], \"content\": \"Amounts equivalent to the excise taxes received on sport fishing equipment and import duties on fishing tackle, yachts and pleasure craft are appropriated into the Sport Fish Restoration Account. Motorboat fuel taxes not transferred to the Boat Safety Account or to the Land and Water Conservation Fund are transferred from the Highway Trust Fund to the Sport Fish Restoration Account. Transfers of motorboat fuel taxes from the Highway Trust Fund to the Land and Water Conservation Fund are limited to $1 million per fiscal year. In addition, pursuant to the Omnibus Budget Reconciliation Act of 1990 [Public Law 101-508, title XI, section 11211(i)(2) and (3)], small engine gasoline taxes are transferred to the Sport Fish Restoration Account.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [140, 957, 798, 1016], \"page_id\": 135}], \"content\": \"Amounts in the Sport Fish Restoration Account are used, as provided by appropriations acts, for the purposes of\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [831, 250, 1490, 556], \"page_id\": 135}], \"content\": \"carrying out \\u201cAn Act to provide that the United States shall aid the States in fish restoration and management projects, and for other purposes,\\u201d approved August 9, 1950 (as in effect on the date of enactment of the Transportation Equity Act for the 21st Century (TEA-21) Restoration Act), the purposes of section 7404(d) of the Transportation Equity for the 21st Century (as in effect on the date of enactment of the TEA-21 Restoration Act), and the Coastal Wetlands Planning, Protection and Restoration Act (as in effect on the date of enactment of the TEA-21 Restoration Act).\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [831, 561, 1490, 679], \"page_id\": 135}], \"content\": \"Amounts in the Boat Safety Account, as provided by appropriations acts, are available to carry out the purposes of section 13106 of title 46, United States Code (as in effect on the date of enactment of the TEA-21 Restoration Act).\", \"description\": null, \"id\": 8, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [831, 681, 1490, 801], \"page_id\": 135}], \"content\": \"When the provisions of 26 United States Code 9602(b) are met, amounts available in the two accounts exceeding outlay requirements are invested in public debt securities with the interest credited to the respective accounts.\", \"description\": null, \"id\": 9, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [831, 804, 1490, 988], \"page_id\": 135}], \"content\": \"Annual reports to Congress, required by 26 United States Code 9602(a), are submitted by the Secretary of the Treasury. These reports are required to cover the financial condition and results of operations of the fund during the past fiscal year and those expected during the next 5 fiscal years.\", \"description\": null, \"id\": 10, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [328, 1072, 1321, 1143], \"page_id\": 135}], \"content\": \"TABLE TF-20.\\u2014Aquatic Resources Trust Fund, Sport Fish Restoration Results of Operations, Fiscal 2002\", \"description\": null, \"id\": 11, \"type\": \"caption\"}, {\"bbox\": [{\"coord\": [153, 1157, 1486, 1857], \"page_id\": 135}], \"content\": \"<table><tr><td colspan=\\\"2\\\">[Source: Bureau of the Public Debt]</td></tr><tr><td>Balance Oct. 1, 2001</td><td>$570,714,381 *</td></tr><tr><td>Revenue:</td><td></td></tr><tr><td>Tax revenue:</td><td></td></tr><tr><td>Gas, motorboat</td><td>212,744,000</td></tr><tr><td>Fish, equipment</td><td>99,118,000</td></tr><tr><td>Electric trolling sonar</td><td>1,264,000</td></tr><tr><td>Customs/import duties</td><td>32,545,116</td></tr><tr><td>Gas, motorboat, small engines</td><td>70,002,000</td></tr><tr><td>Total, tax revenue</td><td>415,673,116</td></tr><tr><td>Investment revenue:</td><td></td></tr><tr><td>Interest on investments</td><td>35,571,717</td></tr><tr><td>Loss on sale of securities</td><td>-</td></tr><tr><td>Total, investment revenue</td><td>35,571,717</td></tr><tr><td>Total revenue</td><td>451,244,833</td></tr><tr><td>Nonexpenditure transfers:</td><td></td></tr><tr><td>Transfer to Interior</td><td>356,647,622</td></tr><tr><td>Transfer to U.S. Coast Guard</td><td>64,000,000</td></tr><tr><td>Transfer to Corps of Engineers</td><td>62,332,369</td></tr><tr><td>Total nonexpenditure transfers</td><td>482,979,991</td></tr><tr><td>Balance Sept. 30, 2002</td><td>$538,97